namespace sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="sidebar-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="settings-loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    <ProfileSection Profile="_editProfile!"
                                    OnSave="SaveProfile"
                                    OnDiscard="DiscardProfileChanges" />
                    break;
                case "notifications":
                    <NotificationsSection Prefs="_editNotifications!"
                                          OnSave="SaveNotifications" />
                    break;
                case "security":
                    <SecuritySection Security="_security!"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession" />
                    break;
                case "appearance":
                    <AppearanceSection Settings="_editAppearance!"
                                       OnSave="SaveAppearance" />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">
                @_toastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    private UserProfile? _savedProfile;
    private UserProfile? _editProfile;
    private NotificationPrefs? _savedNotifications;
    private NotificationPrefs? _editNotifications;
    private SecuritySettings? _security;
    private AppearanceSettings? _savedAppearance;
    private AppearanceSettings? _editAppearance;

    private string? _toastMessage;
    private string _toastType = "success";

    private record SectionInfo(string Key, string Label, string Icon);

    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        _editProfile = _savedProfile with { };
        _savedNotifications = notifTask.Result;
        _editNotifications = _savedNotifications with { MutedChannels = new List<string>(_savedNotifications.MutedChannels) };
        _security = securityTask.Result;
        _savedAppearance = appearanceTask.Result;
        _editAppearance = _savedAppearance with { };
    }

    private async Task SaveProfile()
    {
        await SettingsService.SaveProfileAsync(_editProfile!);
        _savedProfile = _editProfile! with { };
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        _editProfile = _savedProfile! with { };
    }

    private async Task SaveNotifications()
    {
        await SettingsService.SaveNotificationPrefsAsync(_editNotifications!);
        _savedNotifications = _editNotifications! with { MutedChannels = new List<string>(_editNotifications!.MutedChannels) };
        ShowToast("Notification preferences saved!", "success");
    }

    private async Task ChangePassword((string Current, string New) passwords)
    {
        try
        {
            await SettingsService.ChangePasswordAsync(passwords.Current, passwords.New);
            _security = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error: {ex.Message}", "error");
        }
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "success");
    }

    private async Task SaveAppearance()
    {
        await SettingsService.SaveAppearanceAsync(_editAppearance!);
        _savedAppearance = _editAppearance! with { };
        ShowToast("Appearance settings saved!", "success");
    }

    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = null;
    }
}

@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services

<section class="settings-section">
    <h2>Notification Preferences</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="Prefs.EmailNotifications" />
            <span class="toggle-switch"></span>
        </label>

        <label class="toggle-item">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="Prefs.PushNotifications" />
            <span class="toggle-switch"></span>
        </label>

        <label class="toggle-item">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="Prefs.WeeklyDigest" />
            <span class="toggle-switch"></span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _availableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@Prefs.MutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="OnSave">Save Preferences</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter]
    public EventCallback OnSave { get; set; }

    private readonly string[] _availableChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !Prefs.MutedChannels.Contains(channel))
        {
            Prefs.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            Prefs.MutedChannels.Remove(channel);
        }
    }
}

@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services

<section class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>Change Password</span>
            <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
        </button>

        @if (_passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="field-error">@_passwordError</div>
                }
                <button class="btn-primary" @onclick="HandleChangePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="twofa-status">
            <span class="status-indicator @(Security.TwoFactorEnabled ? "enabled" : "disabled")"></span>
            <span>@(Security.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <p class="last-changed">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Security.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session != Security.Sessions.First())
                            {
                                <button class="btn-danger btn-small" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke != null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h3>Revoke Session</h3>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
