@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Settings { get; set; } = default!;

    [Parameter]
    public EventCallback OnSave { get; set; }

    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];

    private readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    private string GetPreviewClasses()
    {
        var theme = Settings.Theme?.ToLowerInvariant() ?? "light";
        var size = Settings.FontSize?.ToLowerInvariant() ?? "medium";
        var compact = Settings.CompactMode ? "compact" : "";
        return $"preview-{theme} preview-{size} {compact}";
    }
}
"}

