arguments.old_str:
@page "/settings"
@rendermode InteractiveServer
@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="sidebar-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="settings-loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    <ProfileSection Profile="_editProfile!"
                                    OnSave="SaveProfile"
                                    OnDiscard="DiscardProfileChanges" />
                    break;
                case "notifications":
                    <NotificationsSection Prefs="_editNotifications!"
                                          OnSave="SaveNotifications" />
                    break;
                case "security":
                    <SecuritySection Security="_security!"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession" />
                    break;
                case "appearance":
                    <AppearanceSection Settings="_editAppearance!"
                                       OnSave="SaveAppearance" />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">
                @_toastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    private UserProfile? _savedProfile;
    private UserProfile? _editProfile;
    private NotificationPrefs? _savedNotifications;
    private NotificationPrefs? _editNotifications;
    private SecuritySettings? _security;
