using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services;

namespace sv_d8ea2394b5a54359ac46b5e44ee63f3c.Components.Pages.Settings;

public class ProfileEditModel
{
    public string DisplayName { get; set; } = "";
    public string Email { get; set; } = "";
    public string AvatarUrl { get; set; } = "";
    public string Bio { get; set; } = "";

    public static ProfileEditModel FromRecord(UserProfile profile) => new()
    {
        DisplayName = profile.DisplayName,
        Email = profile.Email,
        AvatarUrl = profile.AvatarUrl,
        Bio = profile.Bio
    };

    public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
}

public class NotificationEditModel
{
    public bool EmailNotifications { get; set; }
    public bool PushNotifications { get; set; }
    public bool WeeklyDigest { get; set; }
    public List<string> MutedChannels { get; set; } = [];

    public static NotificationEditModel FromRecord(NotificationPrefs prefs) => new()
    {
        EmailNotifications = prefs.EmailNotifications,
        PushNotifications = prefs.PushNotifications,
        WeeklyDigest = prefs.WeeklyDigest,
        MutedChannels = new List<string>(prefs.MutedChannels)
    };

    public NotificationPrefs ToRecord() => new(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
}

public class AppearanceEditModel
{
    public string Theme { get; set; } = "Light";
    public string FontSize { get; set; } = "Medium";
    public string Language { get; set; } = "en";
    public bool CompactMode { get; set; }

    public static AppearanceEditModel FromRecord(AppearanceSettings settings) => new()
    {
        Theme = settings.Theme,
        FontSize = settings.FontSize,
        Language = settings.Language,
        CompactMode = settings.CompactMode
    };

    public AppearanceSettings ToRecord() => new(Theme, FontSize, Language, CompactMode);
}

