@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services

<section class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Model.Theme == theme)"
                           @onchange="() => Model.Theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(Model.FontSize == size)"
                           @onchange="() => Model.FontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Model.Language">
            @foreach (var lang in _languages)
            {
                <option value="@lang.Key">@lang.Value</option>
            }
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="toggle-group">
        <label class="toggle-item">
            <span>Compact Mode</span>
            <input type="checkbox" @bind="Model.CompactMode" />
            <span class="toggle-switch"></span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <div class="preview-content">
            <p class="preview-heading">Sample Heading</p>
            <p class="preview-text">This is how your content will look with the current settings.</p>
            <button class="preview-button">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="OnSave">Save</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public AppearanceEditModel Model { get; set; } = default!;

    [Parameter]
    public EventCallback OnSave { get; set; }

    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];

    private readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    private string GetPreviewClasses()
    {
        var theme = Model.Theme?.ToLowerInvariant() ?? "light";
        var size = Model.FontSize?.ToLowerInvariant() ?? "medium";
        var compact = Model.CompactMode ? "compact" : "";
        return $"preview-{theme} preview-{size} {compact}";
    }
}

