toolArgs.new_str:
@using sv_d8ea2394b5a54359ac46b5e44ee63f3c.Services

<section class="settings-section">
    <h2>Notification Preferences</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="Model.EmailNotifications" />
            <span class="toggle-switch"></span>
        </label>

        <label class="toggle-item">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="Model.PushNotifications" />
            <span class="toggle-switch"></span>
        </label>

        <label class="toggle-item">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="Model.WeeklyDigest" />
            <span class="toggle-switch"></span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _availableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@Model.MutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="OnSave">Save Preferences</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired]
    public NotificationEditModel Model { get; set; } = default!;

    [Parameter]
    public EventCallback OnSave { get; set; }

    private readonly string[] _availableChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !Model.MutedChannels.Contains(channel))
        {
            Model.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            Model.MutedChannels.Remove(channel);
        }
    }
}

